import { Http } from '@nativescript/core';

const DEFAULT_ENDPOINT = 'https://apparel-large-catalog.mock.shop/api';

function resolveEndpoint(): string {
	if (__APPLE__) {
		const value = NSProcessInfo.processInfo.environment.objectForKey('SHOP_API_URL');
		if (value && String(value).length > 0) {
			return String(value);
		}
	}
	return __SHOP_API_URL__ || DEFAULT_ENDPOINT;
}

const endpoint = resolveEndpoint();

export interface Money {
	amount: string;
	currencyCode: string;
}

export interface ImageRef {
	url: string;
	altText: string | null;
}

export interface ProductCard {
	id: string;
	handle: string;
	title: string;
	featuredImage: ImageRef | null;
	priceRange: { minVariantPrice: Money };
	compareAtPriceRange: { minVariantPrice: Money };
}

export interface Collection {
	id: string;
	handle: string;
	title: string;
	image: ImageRef | null;
}

export interface PageInfo {
	hasNextPage: boolean;
	endCursor: string | null;
}

export interface Variant {
	id: string;
	title: string;
	availableForSale: boolean;
	selectedOptions: { name: string; value: string }[];
	price: Money;
	compareAtPrice: Money | null;
}

export interface ProductDetail {
	id: string;
	handle: string;
	title: string;
	description: string;
	images: { nodes: ImageRef[] };
	options: { name: string; optionValues: { name: string }[] }[];
	variants: { nodes: Variant[] };
}

export interface CartLine {
	id: string;
	quantity: number;
	cost: { totalAmount: Money };
	merchandise: {
		id: string;
		title: string;
		image: ImageRef | null;
		product: { handle: string; title: string; featuredImage: ImageRef | null };
	};
}

export interface Cart {
	id: string;
	checkoutUrl: string;
	totalQuantity: number;
	cost: { subtotalAmount: Money };
	lines: { nodes: CartLine[] };
}

export interface CartPayload {
	cart: Cart | null;
	userErrors: { field: string[] | null; message: string }[];
}

export async function gql<T>(operationName: string, query: string, variables: Record<string, unknown> = {}): Promise<T> {
	const response = await Http.request({
		url: endpoint,
		method: 'POST',
		headers: { 'Content-Type': 'application/json' },
		content: JSON.stringify({ operationName, query, variables }),
		timeout: 20000,
	});
	if (response.statusCode < 200 || response.statusCode >= 300) {
		throw new Error(`HTTP ${response.statusCode}`);
	}
	const json = response.content.toJSON();
	if (!json || !json.data) {
		throw new Error(json?.errors?.[0]?.message || 'Empty response');
	}
	return json.data as T;
}
