import type { Money } from './api';

export function formatMoney(money: Money | null | undefined): string {
	if (!money) {
		return '';
	}
	return '$' + Number(money.amount).toFixed(2);
}

export function isDiscounted(price: Money | null | undefined, compareAt: Money | null | undefined): boolean {
	return !!price && !!compareAt && Number(compareAt.amount) > Number(price.amount);
}

export function sizedImageUrl(url: string | null | undefined, width: number): string | null {
	if (!url) {
		return null;
	}
	return url + (url.indexOf('?') === -1 ? '?' : '&') + 'width=' + width;
}
