cat > cart.ts <<'EOF'
import { Dialogs, Observable } from '@nativescript/core';
import { gql, type Cart, type CartPayload } from './api';
import * as ops from './operations';

class CartStore extends Observable {
	cart: Cart | null = null;
	private queue: Promise<unknown> = Promise.resolve();

	get totalQuantity(): number {
		return this.cart ? this.cart.totalQuantity : 0;
	}

	addVariant(merchandiseId: string): Promise<void> {
		return this.enqueue(async () => {
			const lines = [{ merchandiseId, quantity: 1 }];
			if (!this.cart) {
				const data = await gql<{ cartCreate: CartPayload }>('CartCreate', ops.CartCreate, { lines });
				this.apply(data.cartCreate);
			} else {
				const data = await gql<{ cartLinesAdd: CartPayload }>('CartLinesAdd', ops.CartLinesAdd, { cartId: this.cart.id, lines });
				this.apply(data.cartLinesAdd);
			}
		});
	}

	/** Steps a line by `delta`, reading the quantity at execution time so queued taps compound. */
	stepLine(lineId: string, delta: number): Promise<void> {
		return this.enqueue(async () => {
			const line = this.cart?.lines.nodes.find((l) => l.id === lineId);
			if (!this.cart || !line) {
				return;
			}
			const quantity = Math.max(0, line.quantity + delta);
			const data = await gql<{ cartLinesUpdate: CartPayload }>('CartLinesUpdate', ops.CartLinesUpdate, {
				cartId: this.cart.id,
				lines: [{ id: lineId, quantity }],
			});
			this.apply(data.cartLinesUpdate);
		});
	}

	private enqueue(task: () => Promise<void>): Promise<void> {
		const run = this.queue.then(task, task);
		this.queue = run.catch(() => undefined);
		return run;
	}

	private apply(payload: CartPayload) {
		if (payload.cart) {
			this.cart = payload.cart;
			this.notify({ eventName: 'change', object: this });
		}
		if (payload.userErrors && payload.userErrors.length > 0) {
			Dialogs.alert({ message: payload.userErrors[0].message, okButtonText: 'OK' });
		}
	}
}

export const cartStore = new CartStore();
EOF
cat > remote-image.ts <<'EOF'
import { Image, ImageCache, ImageSource } from '@nativescript/core';
import { colors } from './theme';

const cache = new ImageCache.Cache();
cache.maxRequests = 8;
cache.enableDownload();

/** An aspect-fill image that loads through the shared memory cache and tolerates view recycling. */
export class RemoteImage extends Image {
	private currentUrl: string | null = null;

	constructor() {
		super();
		this.stretch = 'aspectFill';
		this.backgroundColor = colors.surface;
	}

	setUrl(url: string | null) {
		if (url === this.currentUrl) {
			return;
		}
		this.currentUrl = url;
		this.imageSource = null;
		if (!url) {
			return;
		}
		const cached = cache.get(url);
		if (cached) {
			this.imageSource = new ImageSource(cached);
			return;
		}
		cache.push({
			key: url,
			url,
			completed: (image: any, key: string) => {
				if (this.currentUrl === key) {
					this.imageSource = new ImageSource(image);
				}
			},
		});
	}
}
