/**
 * Path commands in the design's 24x24 SVG viewBox. Arcs are expressed with their
 * centre so both platforms can draw them without an SVG parser.
 */
type Op =
	| ['M', number, number]
	| ['L', number, number]
	| ['C', number, number, number, number, number, number]
	| ['Z']
	| ['circle', number, number, number]
	/** Clockwise (on screen) arc around (cx, cy) from startDeg to endDeg; 0deg points right. */
	| ['arc', number, number, number, number, number];

const K = 0.5523; // cubic Bézier approximation of a quarter circle

export const icons: Record<string, Op[]> = {
	home: [['M', 3, 10.5], ['L', 12, 3], ['L', 21, 10.5], ['L', 21, 20], ['C', 21, 20 + K, 20 + K, 21, 20, 21], ['L', 15, 21], ['L', 15, 15], ['L', 9, 15], ['L', 9, 21], ['L', 4, 21], ['C', 4 - K, 21, 3, 20 + K, 3, 20], ['Z']],
	search: [['circle', 11, 11, 7], ['M', 20, 20], ['L', 16.5, 16.5]],
	cart: [['M', 6, 7], ['L', 18, 7], ['L', 17, 20], ['L', 7, 20], ['Z'], ['M', 9, 7], ['arc', 12, 7, 3, 180, 360]],
	back: [['M', 15, 5], ['L', 8, 12], ['L', 15, 19]],
	alert: [['circle', 12, 12, 9], ['M', 12, 7.5], ['L', 12, 13], ['M', 12, 16.5], ['L', 12.01, 16.5]],
	minus: [['M', 5, 12], ['L', 19, 12]],
	plus: [['M', 12, 5], ['L', 12, 19], ['M', 5, 12], ['L', 19, 12]],
};

/** Stroked vector icon drawn natively (CAShapeLayer on iOS, ShapeDrawable on Android). */
export class Icon extends View {
	private ops: Op[];
	private strokeColor: Color;
	private lineWidth: number;
	private shapeLayer: CAShapeLayer;
	private paint: android.graphics.Paint;

	constructor(name: keyof typeof icons, size: number, color: Color, lineWidth = 1.75) {
		super();
		this.ops = icons[name];
		this.strokeColor = color;
		this.lineWidth = lineWidth;
		this.width = size;
		this.height = size;
		this.isUserInteractionEnabled = false;
	}

	setColor(color: Color) {
		this.strokeColor = color;
		if (__APPLE__ && this.shapeLayer) {
			this.shapeLayer.strokeColor = color.ios.CGColor;
		} else if (__ANDROID__ && this.paint) {
			this.paint.setColor(color.android);
			(this.nativeViewProtected as android.view.View)?.invalidate();
		}
	}

	createNativeView() {
		if (__APPLE__) {
			const view = UIView.new();
			view.userInteractionEnabled = false;
			const layer = CAShapeLayer.new();
			layer.fillColor = null;
			layer.strokeColor = this.strokeColor.ios.CGColor;
			layer.lineCap = kCALineCapRound;
			layer.lineJoin = kCALineJoinRound;
			view.layer.addSublayer(layer);
			this.shapeLayer = layer;
			return view;
		}
		const view = new android.view.View(this._context);
		const path = new android.graphics.Path();
		for (const op of this.ops) {
			switch (op[0]) {
				case 'M':
					path.moveTo(op[1], op[2]);
					break;
				case 'L':
					path.lineTo(op[1], op[2]);
					break;
				case 'C':
					path.cubicTo(op[1], op[2], op[3], op[4], op[5], op[6]);
					break;
				case 'Z':
					path.close();
					break;
				case 'circle':
					path.addCircle(op[1], op[2], op[3], android.graphics.Path.Direction.CW);
					break;
				case 'arc':
					path.arcTo(new android.graphics.RectF(op[1] - op[3], op[2] - op[3], op[1] + op[3], op[2] + op[3]), op[4], op[5] - op[4], false);
					break;
			}
		}
		const drawable = new android.graphics.drawable.ShapeDrawable(new android.graphics.drawable.shapes.PathShape(path, 24, 24));
		const paint = drawable.getPaint();
		paint.setAntiAlias(true);
		paint.setStyle(android.graphics.Paint.Style.STROKE);
		paint.setStrokeWidth(this.lineWidth);
		paint.setStrokeCap(android.graphics.Paint.Cap.ROUND);
		paint.setStrokeJoin(android.graphics.Paint.Join.ROUND);
		paint.setColor(this.strokeColor.android);
		this.paint = paint;
		view.setBackground(drawable);
		return view;
	}

	onLayout(left: number, top: number, right: number, bottom: number) {
		super.onLayout(left, top, right, bottom);
		if (!__APPLE__ || !this.shapeLayer) {
			return;
		}
		const size = (this.nativeViewProtected as UIView).bounds.size;
		const scale = Math.min(size.width, size.height) / 24;
		const path = UIBezierPath.bezierPath();
		for (const op of this.ops) {
			switch (op[0]) {
				case 'M':
					path.moveToPoint(CGPointMake(op[1], op[2]));
					break;
				case 'L':
					path.addLineToPoint(CGPointMake(op[1], op[2]));
					break;
				case 'C':
					path.addCurveToPointControlPoint1ControlPoint2(CGPointMake(op[5], op[6]), CGPointMake(op[1], op[2]), CGPointMake(op[3], op[4]));
					break;
				case 'Z':
					path.closePath();
					break;
				case 'circle':
					path.moveToPoint(CGPointMake(op[1] + op[3], op[2]));
					path.addArcWithCenterRadiusStartAngleEndAngleClockwise(CGPointMake(op[1], op[2]), op[3], 0, Math.PI * 2, true);
					break;
				case 'arc':
					path.addArcWithCenterRadiusStartAngleEndAngleClockwise(CGPointMake(op[1], op[2]), op[3], (op[4] * Math.PI) / 180, (op[5] * Math.PI) / 180, true);
					break;
			}
		}
		path.applyTransform(CGAffineTransformMakeScale(scale, scale));
		this.shapeLayer.frame = CGRectMake(0, 0, size.width, size.height);
		this.shapeLayer.lineWidth = this.lineWidth * scale;
		this.shapeLayer.path = path.CGPath;
	}
}
EOF

