import { ActivityIndicator, Button, Color, GestureTypes, GridLayout, Label, StackLayout, View } from '@nativescript/core';
import { colors } from './theme';
import { Icon } from './icon';

export function label(text: string, className?: string): Label {
	const l = new Label();
	l.text = text;
	if (className) {
		l.className = className;
	}
	return l;
}

export function button(text: string, className: string, onTap: () => void, testID?: string): Button {
	const b = new Button();
	b.text = text;
	b.className = className;
	b.on('tap', onTap);
	if (testID) {
		b.testID = testID;
	}
	return b;
}

export function onTap(view: View, handler: () => void) {
	view.on(GestureTypes[GestureTypes.tap], handler);
}

export function grid(columns?: string, rows?: string): GridLayout {
	const g = new GridLayout();
	if (columns) {
		g.columns = columns;
	}
	if (rows) {
		g.rows = rows;
	}
	return g;
}

export function stack(horizontal = false): StackLayout {
	const s = new StackLayout();
	if (horizontal) {
		s.orientation = 'horizontal';
	}
	return s;
}

export function place<T extends View>(view: T, row: number, col = 0): T {
	GridLayout.setRow(view, row);
	GridLayout.setColumn(view, col);
	return view;
}

export function block(width: number | 'auto', height: number, radius: number, color: Color = colors.skeleton): View {
	const v = new GridLayout();
	v.width = width;
	v.height = height;
	v.borderRadius = radius;
	v.backgroundColor = color;
	return v;
}

export function spinner(): View {
	const a = new ActivityIndicator();
	a.busy = true;
	a.horizontalAlignment = 'center';
	a.verticalAlignment = 'middle';
	return a;
}

/** Centered "Couldn't load products" state with a Retry button. */
export function errorState(onRetry: () => void): View {
	const outer = grid();
	outer.backgroundColor = colors.background;
	const s = stack();
	s.verticalAlignment = 'middle';
	s.horizontalAlignment = 'center';
	s.padding = '0 32';
	const icon = new Icon('alert', 48, colors.textMuted, 1.25);
	icon.horizontalAlignment = 'center';
	s.addChild(icon);
	const title = label("Couldn't load products", 'section-title');
	title.textAlignment = 'center';
	title.marginTop = 12;
	s.addChild(title);
	const body = label('Check your connection and try again.', 'body muted');
	body.textAlignment = 'center';
	body.textWrap = true;
	body.marginTop = 12;
	s.addChild(body);
	const retry = button('Retry', 'btn-secondary', onRetry, 'error-retry');
	retry.marginTop = 20;
	retry.horizontalAlignment = 'center';
	s.addChild(retry);
	outer.addChild(s);
	return outer;
}

/** Shows exactly one child of a single-cell grid. */
export class StateHost {
	readonly view = grid();
	private current: View | null = null;

	show(child: View) {
		if (this.current === child) {
			return;
		}
		if (this.current) {
			this.view.removeChild(this.current);
		}
		this.current = child;
		this.view.addChild(child);
	}
}
EOF

