import { Frame, GridLayout, Label, Page, View } from '@nativescript/core';
import { cartStore } from './lib/cart';
import { Icon } from './lib/icon';
import { colors, screenWidth } from './lib/theme';
import { grid, label, onTap, place, stack } from './lib/ui';
import { createHomePage } from './pages/home';
import { createSearchPage } from './pages/search';
import { createCartPage } from './pages/cart';

interface TabSpec {
	id: string;
	title: string;
	icon: 'home' | 'search' | 'cart';
	create: () => Page;
}

const TABS: TabSpec[] = [
	{ id: 'tab-home', title: 'Home', icon: 'home', create: createHomePage },
	{ id: 'tab-search', title: 'Search', icon: 'search', create: createSearchPage },
	{ id: 'tab-cart', title: 'Cart', icon: 'cart', create: createCartPage },
];

interface TabButton {
	icon: Icon;
	label: Label;
}

const HIDES_TAB_BAR = '__hidesTabBar';

class Shell {
	private root: GridLayout;
	private tabBar: GridLayout;
	private frames: (Frame | null)[] = [null, null, null];
	private buttons: TabButton[] = [];
	private badge: Label;
	private selected = -1;

	createRoot(): View {
		this.root = grid(undefined, '*, auto');
		this.root.backgroundColor = colors.background;
		this.tabBar = this.createTabBar();
		this.root.addChild(place(this.tabBar, 1));
		this.select(0);
		cartStore.on('change', () => this.updateBadge());
		return this.root;
	}

	select(index: number) {
		if (index === this.selected) {
			return;
		}
		if (!this.frames[index]) {
			const frame = new Frame();
			frame.navigate({ create: TABS[index].create, animated: false });
			this.frames[index] = frame;
			this.root.insertChild(place(frame, 0), 0);
		}
		this.frames.forEach((frame, i) => {
			if (frame) {
				frame.visibility = i === index ? 'visible' : 'collapse';
			}
		});
		this.buttons.forEach((b, i) => {
			const active = i === index;
			b.icon.setColor(active ? colors.text : colors.textMuted);
			b.label.className = active ? 'tab-label active' : 'tab-label';
		});
		this.selected = index;
		this.syncTabBar();
	}

	/** Pages created with `hidesTabBar` collapse the tab bar while they are on top of the selected tab. */
	syncTabBar(incoming?: Page) {
		const frame = this.frames[this.selected];
		let page = frame?.currentPage;
		if (incoming && incoming.frame === frame) {
			page = incoming;
		}
		const hidden = !!(page && (page as any)[HIDES_TAB_BAR]);
		this.tabBar.visibility = hidden ? 'collapse' : 'visible';
	}

	markHidesTabBar(page: Page) {
		(page as any)[HIDES_TAB_BAR] = true;
	}

	private createTabBar(): GridLayout {
		const bar = grid('*, *, *');
		bar.height = 49;
		bar.backgroundColor = colors.background;
		bar.borderTopWidth = 1;
		bar.borderTopColor = colors.border;
		TABS.forEach((tab, i) => {
			const cell = grid();
			cell.testID = tab.id;
			const content = stack();
			content.verticalAlignment = 'middle';
			content.horizontalAlignment = 'center';
			const icon = new Icon(tab.icon, 24, colors.textMuted);
			icon.horizontalAlignment = 'center';
			const text = label(tab.title, 'tab-label');
			text.marginTop = 2;
			content.addChild(icon);
			content.addChild(text);
			cell.addChild(content);
			if (tab.icon === 'cart') {
				this.badge = label('', 'badge');
				this.badge.testID = 'cart-badge';
				this.badge.horizontalAlignment = 'left';
				this.badge.verticalAlignment = 'top';
				this.badge.marginTop = 4;
				this.badge.marginLeft = screenWidth / 6 + 6;
				this.badge.visibility = 'collapse';
				cell.addChild(this.badge);
			}
			onTap(cell, () => this.select(i));
			bar.addChild(place(cell, 0, i));
			this.buttons.push({ icon, label: text });
		});
		return bar;
	}

	private updateBadge() {
		const count = cartStore.totalQuantity;
		this.badge.text = String(count);
		this.badge.visibility = count > 0 ? 'visible' : 'collapse';
	}
}

export const shell = new Shell();

/** Standard screen: no native action bar; optionally hides the tab bar while on top. */
export function createPage(hidesTabBar = false): Page {
	const page = new Page();
	page.actionBarHidden = true;
	page.backgroundColor = colors.background;
	if (hidesTabBar) {
		shell.markHidesTabBar(page);
	}
	page.on(Page.navigatingToEvent, () => shell.syncTabBar(page));
	page.on(Page.navigatedToEvent, () => shell.syncTabBar());
	return page;
}
EOF
cat > app.ts <<'EOF'
import { Application } from '@nativescript/core';
import { shell } from './shell';

Application.run({ create: () => shell.createRoot() });
EOF

