		const chip = button(c.title, 'chip', () => openCollection(page, c.handle, c.title), `collection-chip-${i}`);
		if (i < collections.length - 1) {
			chip.marginRight = 8;
		}
		chipRow.addChild(chip);
	});
	body.addChild(horizontalScroller(chipRow));

	const featured = collections[0];
	if (featured) {
		const banner = grid();
