		banner.height = 240;
		banner.margin = '4 16 0';
		banner.borderRadius = 12;
		banner.backgroundColor = colors.surface;
		const img = new RemoteImage();
		img.setUrl(sizedImageUrl(featured.image?.url, 1080));
