		title.fontSize = 20;
		title.fontWeight = '700';
		title.marginTop = 2;
		title.textWrap = true;
		const cta = label('Shop now');
		cta.color = colors.white;
		cta.fontSize = 14;
		cta.marginTop = 2;
		scrim.addChild(kicker);
		scrim.addChild(title);
		scrim.addChild(cta);
		banner.addChild(scrim);
		onTap(banner, () => openCollection(page, featured.handle, featured.title));
		body.addChild(banner);
	}

	const collectionsTitle = label('Collections', 'section-title');
	collectionsTitle.padding = '28 16 12';
	body.addChild(collectionsTitle);
	const cards = stack(true);
	cards.padding = '0 16';
	collections.forEach((c, i) => {
		const card = stack();
		card.testID = `collection-card-${i}`;
		card.width = 140;
		if (i < collections.length - 1) {
			card.marginRight = 12;
		}
		const img = new RemoteImage();
		img.height = 175;
		img.borderRadius = 8;
		img.setUrl(sizedImageUrl(c.image?.url, 480));
		const t = label(c.title, 'card-title');
		t.fontWeight = '600';
		t.textWrap = true;
		t.marginTop = 8;
		card.addChild(img);
		card.addChild(t);
		onTap(card, () => openCollection(page, c.handle, c.title));
		cards.addChild(card);
	});
	body.addChild(horizontalScroller(cards));

	const bestTitle = label('Best sellers', 'section-title');
	bestTitle.padding = '28 16 12';
	body.addChild(bestTitle);
	const gridView = new GridLayout();
	gridView.columns = '*, 12, *';
	gridView.padding = '0 16';
	const rowCount = Math.ceil(products.length / 2);
	gridView.rows = Array.from({ length: rowCount }, () => 'auto').join(', ');
	products.forEach((p, i) => {
		const card = new ProductCardView(gridImageHeight, (product) => openProduct(page, product));
		card.bind(p, `best-seller-${i}`);
		const row = Math.floor(i / 2);
		if (row < rowCount - 1) {
			card.view.marginBottom = 20;
		}
		gridView.addChild(place(card.view, row, (i % 2) * 2));
	});
	body.addChild(gridView);

	const scroll = new ScrollView();
	scroll.testID = 'home-scroll';
	scroll.content = body;
	return scroll;
}

export function createHomePage(): Page {
	const page = createPage();
	const host = new StateHost();
	const loading = skeleton();
	let failed: View | null = null;

	const load = () => {
		host.show(loading);
		gql<HomeData>('Home', ops.Home).then(
			(data) => {
				const content = buildContent(page, data);
				content.once(View.layoutChangedEvent, () => markHomeReady());
				host.show(content);
			},
			() => {
				failed = failed || errorWithHeader(load);
				host.show(failed);
			},
		);
	};

	page.content = host.view;
	load();
	return page;
}

function errorWithHeader(retry: () => void): View {
	const g = grid(undefined, 'auto, *');
	g.addChild(place(header(), 0));
	g.addChild(place(errorState(retry), 1));
	return g;
}
