import { ProductCardView } from '../lib/product-card';
import { gridImageHeight } from '../lib/theme';
import { button, errorState, grid, label, place, spinner, stack } from '../lib/ui';
import { createPage } from '../shell';

interface CollectionData {
	collection: {
		id: string;
		title: string;
		description: string;
		products: { pageInfo: PageInfo; nodes: ProductCard[] };
	} | null;
}

const SORTS = [
	{ id: 'sort-featured', label: 'Featured', sortKey: 'COLLECTION_DEFAULT', reverse: false },
	{ id: 'sort-best-selling', label: 'Best selling', sortKey: 'BEST_SELLING', reverse: false },
	{ id: 'sort-price-asc', label: 'Price: low to high', sortKey: 'PRICE', reverse: false },
	{ id: 'sort-price-desc', label: 'Price: high to low', sortKey: 'PRICE', reverse: true },
];

const ROW_GAP = 20;
const ROW_HEIGHT = gridImageHeight + 8 + 36 + 8 + 20 + ROW_GAP;

export function createCollectionPage(handle: string, initialTitle: string) {
	const page = createPage();
	const root = grid(undefined, 'auto, auto, auto, *');
	const bar = navBar(page, initialTitle);
	root.addChild(place(bar.view, 0));

	const description = label('', 'caption');
	description.fontSize = 14;
	description.textWrap = true;
	description.padding = '4 16 0';
	description.visibility = 'collapse';
	root.addChild(place(description, 1));

	let sort = SORTS[0];
	const sortButtons: Button[] = [];
	const sortRow = stack(true);
	sortRow.padding = '12 16';
	SORTS.forEach((s) => {
		const b = button(s.label, 'sort', () => {
			if (sort === s) {
				return;
			}
			sort = s;
			updateSortButtons();
			showLoading();
			list.reload();
		}, s.id);
		sortButtons.push(b);
		sortRow.addChild(b);
	});
	const updateSortButtons = () => sortButtons.forEach((b, i) => (b.className = SORTS[i] === sort ? 'sort selected' : 'sort'));
	updateSortButtons();
	const sortScroll = new ScrollView();
	sortScroll.orientation = 'horizontal';
	sortScroll.scrollBarIndicatorVisible = false;
	sortScroll.content = sortRow;
	root.addChild(place(sortScroll, 2));

	const createRow = (): View => {
		const row = grid('*, 12, *');
		row.padding = `0 16 ${ROW_GAP}`;
		const cards = [0, 1].map(() => new ProductCardView(gridImageHeight, (p) => openProduct(page, p)));
		row.addChild(place(cards[0].view, 0, 0));
		row.addChild(place(cards[1].view, 0, 2));
		(row as any).cards = cards;
		return row;
	};
	const bindRow = (view: View, items: ProductCard[], start: number) => {
		const cards: ProductCardView[] = (view as any).cards;
		cards.forEach((card, i) => {
			const product = items[i];
			if (product) {
				card.bind(product, `product-card-${start + i}`);
				card.view.visibility = 'visible';
			} else {
				card.view.visibility = 'hidden';
			}
		});
	};

	const body = new GridLayout();
	const overlay = grid();
	let errorView: View | null = null;
	const loadingView = spinner();
	const showLoading = () => {
		overlay.removeChildren();
		overlay.addChild(loadingView);
		overlay.visibility = 'visible';
	};

	const list = new PagedList<ProductCard>(
		2,
		ROW_HEIGHT,
		createRow,
		bindRow,
		async (after) => {
			const data = await gql<CollectionData>('CollectionProducts', ops.CollectionProducts, {
				handle,
				first: 24,
				after,
				sortKey: sort.sortKey,
				reverse: sort.reverse,
			});
			const c = data.collection;
			if (!c) {
				throw new Error('Collection not found');
			}
			bar.title.text = c.title;
			description.text = c.description;
			description.visibility = c.description ? 'visible' : 'collapse';
			return { nodes: c.products.nodes, hasNextPage: c.products.pageInfo.hasNextPage, endCursor: c.products.pageInfo.endCursor };
		},
		(error) => {
			if (error) {
				errorView = errorView || errorState(() => {
					showLoading();
					list.reload();
				});
				overlay.removeChildren();
				overlay.addChild(errorView);
			} else {
				overlay.visibility = 'collapse';
			}
		},
	);
	list.listView.testID = 'product-grid';
	body.addChild(list.listView);
	body.addChild(overlay);
	overlay.backgroundColor = '#FFFFFF' as any;
	root.addChild(place(body, 3));

	page.content = root;
	showLoading();
	list.reload();
	return page;
}
