import { Button, Dialogs, FormattedString, Label, Page, ScrollEventData, ScrollView, Span, StackLayout, View, WrapLayout } from '@nativescript/core';
import { gql, type ProductCard, type ProductDetail, type Variant } from '../lib/api';
import { cartStore } from '../lib/cart';
import { formatMoney, isDiscounted, sizedImageUrl } from '../lib/format';
import { Icon } from '../lib/icon';
import { goBack, openProduct } from '../lib/navigation';
import * as ops from '../lib/operations';
import { RemoteImage } from '../lib/remote-image';
import { colors, screenWidth } from '../lib/theme';
import { button, errorState, grid, label, onTap, place, spinner, stack, StateHost } from '../lib/ui';
import { createPage, shell } from '../shell';

interface ProductData {
	product: ProductDetail | null;
	productRecommendations: ProductCard[] | null;
}

const IMAGE_HEIGHT = Math.round((screenWidth * 4) / 3);

function visibleOptions(product: ProductDetail) {
	return product.options.filter((o) => !(o.name === 'Title' && o.optionValues.length === 1 && o.optionValues[0].name === 'Default Title'));
}

function initialVariant(product: ProductDetail): Variant | undefined {
	const variants = product.variants.nodes;
	return variants.find((v) => v.availableForSale) || variants[0];
}

function findVariant(product: ProductDetail, current: Variant | undefined, name: string, value: string): Variant | undefined {
	const wanted = new Map<string, string>();
	current?.selectedOptions.forEach((o) => wanted.set(o.name, o.value));
	wanted.set(name, value);
	const variants = product.variants.nodes;
	const exact = variants.find((v) => v.selectedOptions.every((o) => wanted.get(o.name) === o.value));
	if (exact) {
		return exact;
	}
	const matching = variants.filter((v) => v.selectedOptions.some((o) => o.name === name && o.value === value));
	return matching.find((v) => v.availableForSale) || matching[0];
}

function carousel(product: ProductDetail): View {
