import { Label, Page, ScrollView, StackLayout, Utils, View } from '@nativescript/core';
import type { CartLine } from '../lib/api';
import { cartStore } from '../lib/cart';
import { formatMoney, sizedImageUrl } from '../lib/format';
import { Icon } from '../lib/icon';
import { RemoteImage } from '../lib/remote-image';
import { colors } from '../lib/theme';
import { button, grid, label, onTap, place, stack } from '../lib/ui';
import { createPage, shell } from '../shell';

function openCheckout(url: string) {
	if (__APPLE__) {
		const safari = SFSafariViewController.alloc().initWithURL(NSURL.URLWithString(url));
		let top = Utils.ios.getRootViewController();
		while (top && top.presentedViewController) {
			top = top.presentedViewController;
		}
		top?.presentViewControllerAnimatedCompletion(safari, true, null);
	} else {
		Utils.openUrl(url);
	}
}

function stepperButton(iconName: 'minus' | 'plus', testID: string, handler: () => void): View {
	const b = grid();
	b.testID = testID;
	b.width = 36;
	b.height = 34;
	const icon = new Icon(iconName, 16, colors.text, 2);
	icon.horizontalAlignment = 'center';
	icon.verticalAlignment = 'middle';
	b.addChild(icon);
	onTap(b, handler);
	return b;
}

function lineView(line: CartLine, index: number): View {
	const row = grid('80, *');
	row.testID = `cart-line-${index}`;
	row.padding = '16 0';
	row.borderBottomWidth = 1;
	row.borderBottomColor = colors.border;

	const image = new RemoteImage();
	image.width = 80;
	image.height = 107;
	image.borderRadius = 8;
	const merch = line.merchandise;
	image.setUrl(sizedImageUrl((merch.image || merch.product.featuredImage)?.url, 240));
	row.addChild(place(image, 0, 0));

	const info = grid(undefined, 'auto, auto, *, auto');
	info.marginLeft = 12;
	const title = label(merch.product.title, 'body');
	title.fontWeight = '600';
	title.textWrap = true;
	info.addChild(place(title, 0));
	if (merch.title !== 'Default Title') {
		const variant = label(merch.title, 'caption');
		variant.marginTop = 4;
		info.addChild(place(variant, 1));
	}

	const bottom = grid('auto, *, auto');
	bottom.marginTop = 4;
	const stepper = stack(true);
	stepper.height = 36;
	stepper.borderWidth = 1;
	stepper.borderColor = colors.border;
	stepper.borderRadius = 12;
	stepper.addChild(stepperButton('minus', `qty-dec-${index}`, () => cartStore.stepLine(line.id, -1).catch(() => undefined)));
	const qty = label(String(line.quantity));
	qty.minWidth = 24;
	qty.textAlignment = 'center';
	qty.fontSize = 15;
	qty.fontWeight = '600';
	qty.verticalAlignment = 'middle';
	stepper.addChild(qty);
	stepper.addChild(stepperButton('plus', `qty-inc-${index}`, () => cartStore.stepLine(line.id, 1).catch(() => undefined)));
	bottom.addChild(place(stepper, 0, 0));
	const total = label(formatMoney(line.cost.totalAmount), 'price');
	total.verticalAlignment = 'middle';
	bottom.addChild(place(total, 0, 2));
	info.addChild(place(bottom, 3));

	row.addChild(place(info, 0, 1));
	return row;
}

function emptyState(): View {
	const s = stack();
	s.verticalAlignment = 'middle';
	s.horizontalAlignment = 'center';
	s.padding = '0 32';
	const icon = new Icon('cart', 48, colors.textMuted, 1.25);
	icon.horizontalAlignment = 'center';
	s.addChild(icon);
	const title = label('Your cart is empty', 'section-title');
	title.textAlignment = 'center';
	title.marginTop = 12;
	s.addChild(title);
	const body = label('Items you add will appear here.', 'body muted');
	body.textAlignment = 'center';
	body.textWrap = true;
	body.marginTop = 12;
	s.addChild(body);
	const start = button('Start shopping', 'btn-primary', () => shell.select(0));
	start.height = 48;
	start.padding = '0 24';
	start.marginTop = 20;
	start.horizontalAlignment = 'center';
	s.addChild(start);
	return s;
}

export function createCartPage(): Page {
	const page = createPage();
	const root = grid(undefined, 'auto, *, auto');

	const header = grid();
	header.height = 44;
	header.padding = '0 16';
	const title = label('Cart', 'screen-title');
	title.verticalAlignment = 'middle';
	header.addChild(title);
	root.addChild(place(header, 0));

	const empty = emptyState();
	root.addChild(place(empty, 1));

	const linesStack = new StackLayout();
	linesStack.padding = '0 16';
	const scroll = new ScrollView();
	scroll.content = linesStack;
	root.addChild(place(scroll, 1));

	const summary = stack();
	summary.padding = 16;
	summary.borderTopWidth = 1;
	summary.borderTopColor = colors.border;
	summary.backgroundColor = colors.background;
	const subtotalRow = grid('*, auto');
	const subtotalLabel = label('Subtotal', 'body');
	subtotalLabel.verticalAlignment = 'bottom';
	subtotalRow.addChild(place(subtotalLabel, 0, 0));
	const subtotal: Label = label('', 'section-title');
	subtotal.testID = 'cart-subtotal';
	subtotalRow.addChild(place(subtotal, 0, 1));
	summary.addChild(subtotalRow);
	const note = label('Taxes and shipping are calculated at checkout.', 'caption');
	note.textWrap = true;
	note.marginTop = 12;
	summary.addChild(note);
	const checkout = button(
		'Check out',
		'btn-primary',
		() => {
			if (cartStore.cart) {
				openCheckout(cartStore.cart.checkoutUrl);
			}
		},
		'checkout',
	);
	checkout.marginTop = 12;
	summary.addChild(checkout);
	root.addChild(place(summary, 2));

	const render = () => {
		const cart = cartStore.cart;
		const lines = cart ? cart.lines.nodes : [];
		const hasLines = lines.length > 0;
		empty.visibility = hasLines ? 'collapse' : 'visible';
		scroll.visibility = hasLines ? 'visible' : 'collapse';
		summary.visibility = hasLines ? 'visible' : 'collapse';
		linesStack.removeChildren();
		lines.forEach((line, i) => linesStack.addChild(lineView(line, i)));
		subtotal.text = cart ? formatMoney(cart.cost.subtotalAmount) : '';
	};
	cartStore.on('change', render);
	render();

	page.content = root;
	return page;
}
