import { ActivityIndicator, Color, ItemEventData, ListView, View } from '@nativescript/core';
import { screenHeight } from './theme';
import { grid } from './ui';

export interface PageResult<T> {
	nodes: T[];
	hasNextPage: boolean;
	endCursor: string | null;
}

interface Row<T> {
	kind: 'row' | 'footer';
	items: T[];
	start: number;
}

/**
 * Cursor-paginated, lazily rendered list built on the core ListView with fixed-height rows. Groups
 * `perRow` items per row, appends a spinner row while a page loads, and requests the next page once the user is
 * within one screen height of the end.
 */
export class PagedList<T> {
	readonly listView = new ListView();
	private nodes: T[] = [];
	private rows: Row<T>[] = [];
	private hasNextPage = false;
	private endCursor: string | null = null;
	private loading = false;
	private generation = 0;
	private prefetchRows: number;

	constructor(
		private perRow: number,
		rowHeight: number,
		createRow: () => View,
		bindRow: (view: View, items: T[], start: number) => void,
		private fetchPage: (after: string | null) => Promise<PageResult<T>>,
		private onFirstPage: (error: unknown | null) => void,
	) {
		this.prefetchRows = Math.ceil(screenHeight / rowHeight) + 1;
		const lv = this.listView;
		// UITableView detaches cells on every reloadData; core ListView responds by tearing the row's
		// native views down and rebuilding them on reuse. Rebuilding intermittently crashed on iOS
		// (UIColor resolution on a freed object), so rows keep their native views for the list's life.
		if (__APPLE__) {
			(lv as any)._removeContainer = () => {};
		}
		lv.separatorColor = new Color(0, 0, 0, 0);
		lv.rowHeight = rowHeight;
		// rowHeight is coerced to 'auto' until the native view exists; without a fixed height the
		// iOS ListView measures (and binds) every row up front instead of rendering lazily.
		lv.on(View.loadedEvent, () => (lv as any).updateEffectiveRowHeight());
		lv.itemTemplates = [
			{ key: 'row', createView: createRow },
			{ key: 'footer', createView: createFooter },
		];
		lv.itemTemplateSelector = (item: Row<T> | undefined) => (item ? item.kind : 'footer');
		lv.on(ListView.itemLoadingEvent, (args: ItemEventData) => {
			if (__APPLE__ && args.ios) {
				(args.ios as UITableViewCell).selectionStyle = UITableViewCellSelectionStyle.None;
			}
			const row = this.rows[args.index];
			if (row && row.kind === 'row') {
				bindRow(args.view, row.items, row.start);
			}
			if (args.index >= this.rows.length - this.prefetchRows) {
				setTimeout(() => this.loadMoreIfNearEnd(), 0);
			}
		});
	}

	/** Clears the list and loads the first page. */
	reload() {
		this.generation++;
		this.nodes = [];
		this.hasNextPage = false;
		this.endCursor = null;
		this.loading = false;
		this.render();
		this.fetch(null);
	}

	/** Drops the current results and ignores any response still in flight. */
	cancel() {
		this.generation++;
		this.nodes = [];
		this.hasNextPage = false;
		this.endCursor = null;
		this.loading = false;
		this.render();
	}

	/**
	 * Checks the real scroll position rather than trusting itemLoading alone: XCUITest's
	 * accessibility snapshot makes UITableView build off-screen cells, which would otherwise
	 * page through the whole catalog.
	 */
	private loadMoreIfNearEnd() {
		if (this.loading || !this.hasNextPage) {
			return;
		}
		if (__APPLE__) {
			const table = this.listView.ios as UITableView;
			if (!table) {
				return;
			}
			const viewport = table.bounds.size.height;
